 539   public getExternalContextAsArray(project: Project): { fileName: string; content: string; type: string }[] {
 540       if (!this.context?.externalContext) return [];
 541       const externalContextArray = [];
 542       for (const fileId of Object.keys(this.context.externalContext)) {
 543           const file = project.externalContext?.find(f => f.id === fileId);
 544           if (file) {
 545               externalContextArray.push({
 546                   fileName: file.fileName,
 547                   content: file.content,
 548                   type: this.context.externalContext[fileId]!,
 549               });
 550           }
 551       }
 552       return externalContextArray;
 553   }
